import{_ as a,o as t,c as r,m as i}from"./chunks/framework.D3-xQjZb.js";const p=JSON.parse('{"title":"Site notes","description":"How Keith Williams’s journal and Ordo Knowledge Lab handle sharing, search, contact, artwork, sources, and requests to reuse the work.","frontmatter":{"title":"Site notes","description":"How Keith Williams’s journal and Ordo Knowledge Lab handle sharing, search, contact, artwork, sources, and requests to reuse the work.","teaser":"What happens when you read, share, or reuse something from this site, and how to reach Keith about a correction or accessibility problem."},"headers":[],"relativePath":"site-notes.md","filePath":"site-notes.md"}'),n={name:"site-notes.md"};function o(s,e,d,h,l,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="site-notes" tabindex="-1">Site notes <a class="header-anchor" href="#site-notes" aria-label="Permalink to &quot;Site notes&quot;">​</a></h1><p>I publish this journal and Ordo Knowledge Lab as an educator and software builder. The views here are my own.</p><h2 id="report-a-correction-or-accessibility-problem" tabindex="-1">Report a correction or accessibility problem <a class="header-anchor" href="#report-a-correction-or-accessibility-problem" aria-label="Permalink to &quot;Report a correction or accessibility problem&quot;">​</a></h2><p>Send me the page link and tell me what you encountered. If a passage misquotes a source, include the original passage. If a page is hard to use with a keyboard or screen reader, tell me which action you were trying to take. <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Contact Keith through NJIT</a></p><h2 id="teaching-and-reuse" tabindex="-1">Reuse a lesson or illustration <a class="header-anchor" href="#teaching-and-reuse" aria-label="Permalink to &quot;Reuse a lesson or illustration {#teaching-and-reuse}&quot;">​</a></h2><p>The teacher Studio includes instructions for adapting the assignment. Give students <code>LESSON.md</code> and <code>AGENTS.md</code>. Keep the worked answers in your teaching copy. For software, images, and third-party readings, check the terms attached to the original work. If you want to republish an article or illustration and the terms are unclear, send me the page link and how you plan to use it. <a href="https://keithwilliams.org/downloads/AI-Studio-Starter.zip" target="_blank" rel="noreferrer">Download the teacher Studio</a> · <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Ask about reuse</a></p><h2 id="sharing-and-getting-in-touch" tabindex="-1">Share an article <a class="header-anchor" href="#sharing-and-getting-in-touch" aria-label="Permalink to &quot;Share an article {#sharing-and-getting-in-touch}&quot;">​</a></h2><p><strong>Copy link</strong> copies the public page address. <strong>Share on LinkedIn</strong> opens LinkedIn with that address so you can review your post. On supported devices, the additional sharing option opens your device’s share menu. You choose the destination. <a href="https://www.linkedin.com/legal/privacy-policy" target="_blank" rel="noreferrer">LinkedIn privacy policy</a></p><h2 id="student-support-and-independent-inquiries" tabindex="-1">Student support and independent inquiries <a class="header-anchor" href="#student-support-and-independent-inquiries" aria-label="Permalink to &quot;Student support and independent inquiries&quot;">​</a></h2><p>Enrolled students should use their usual private course channel for questions about assignments or grades. A GitHub project discussion is public. For an independent consulting inquiry, describe the work your team wants help with in a private message. <a href="https://www.linkedin.com/in/keithwilliams5/" target="_blank" rel="noreferrer">Contact Keith on LinkedIn</a></p><h2 id="reading-and-searching" tabindex="-1">Reading and searching <a class="header-anchor" href="#reading-and-searching" aria-label="Permalink to &quot;Reading and searching&quot;">​</a></h2><p>GitHub Pages hosts both publications and logs visitors’ IP addresses for security. I haven’t added advertising pixels or visitor analytics to these pages. The Knowledge Lab searches a downloaded index in your browser. It keeps the current search in tab-session storage and can remember display preferences on your device. Reading an example or a prompt here doesn’t send it to an AI service. <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection" target="_blank" rel="noreferrer">GitHub Pages data collection</a> · <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub privacy statement</a></p><h2 id="artwork-audio-and-sources" tabindex="-1">Artwork, audio, and sources <a class="header-anchor" href="#artwork-audio-and-sources" aria-label="Permalink to &quot;Artwork, audio, and sources&quot;">​</a></h2><p>I use AI-generated illustrations to explain ideas. The author portrait is an AI-assisted adaptation of a photograph of me. The optional audio introduction uses a synthetic voice, and its transcript is next to the player. Technical diagrams, references, and links to original materials appear with the work they support.</p><h2 id="type-and-lettering" tabindex="-1">Type and lettering <a class="header-anchor" href="#type-and-lettering" aria-label="Permalink to &quot;Type and lettering&quot;">​</a></h2><p>This journal pairs Source Serif 4 for reading with Source Sans 3 for navigation. Frank Grießhammer designed the serif family and Paul D. Hunt designed its sans companion. Both typefaces load from this site. The GitHub and LinkedIn symbols come from Font Awesome Free by Fonticons and link to my public profiles. <a href="/type/source-serif-4-OFL.txt">Source Serif license</a> · <a href="/type/source-sans-3-OFL.txt">Source Sans license</a> · <a href="/icons/font-awesome-license.txt">Icon credits and license</a></p>',16)])])}const g=a(n,[["render",o]]);export{p as __pageData,g as default};
